ST.xhtml:p:
(*外部控制耦合方向*)
IF g_diDustGearDirect =1.0 THEN
  nDirect := 1.0;
END_IF;
IF dCoordMaxDiff <=0.0 THEN
  dCoordMaxDiff := 20.0;
END_IF;

R_Trigger1(CLK := g_biDAxisGearIn OR g_bDAxisGearIn OR bGearIn);
R_Trigger2(CLK := g_biDAxisGearOut OR g_bDAxisGearOut OR bGearOut);
IF R_Trigger1.Q THEN
  IF D_Axis.NCTOPLC.AxisState <> 8 THEN
    nGearState := 10;
    g_bDAxisGearDone :=FALSE;
    g_boDAxisGearDone :=FALSE;
    bGearDone :=FALSE;
  END_IF;
  bGearIn := FALSE;
END_IF;
IF R_Trigger2.Q THEN
  IF D_Axis.NCTOPLC.AxisState = 8 THEN
    nGearState := 20;
    g_bDAxisGearDone :=FALSE;                                                                                                                
    g_boDAxisGearDone :=FALSE;
    bGearDone :=FALSE;
    bGearOut :=FALSE;
  END_IF;
END_IF;
CASE nGearState OF
  0:
    nGearState :=0;
  10:
    DustAxis_GearIn.EXECUTE :=TRUE;
    DustAxis_GearIn.RATIONUMERATOR := 1.0*nDirect;
    DustAxis_GearIn.RATIODENOMINATOR := 1;
    IF DustAxis_GearIn.InGear THEN
      g_bDAxisGearDone :=TRUE;
      g_boDAxisGearDone :=TRUE;
      bGearDone :=TRUE;
      dCoordY := g_fCurrentCoordYBuffer;
      dCoordD := D_Axis.NCTOPLC.ACTPOS;
      dCoordDiff := ABS(g_fCurrentCoordYBuffer - D_Axis.NCTOPLC.ACTPOS);
      bGearCheck := TRUE;
      nGearState := 40;
    END_IF;
    IF DustAxis_GearIn.Error OR DustAxis_GearIn.CommandAborted THEN
      DustAxis_GearIn.Execute := FALSE;
      g_noDAxisGearErrorID := DustAxis_GearIn.ERRORID;
      g_bDAxisGearInError := TRUE;
      nGearState := 0;
    END_IF;
  20:
    DustAxis_GearIn.Execute := FALSE;
    DustAxis_GearOut.Execute := TRUE;
    IF DustAxis_GearOut.Done THEN
      DustAxis_GearOut.Execute := FALSE;
      IF D_Axis.NCTOPLC.AxisState = 2 THEN
        bGearCheck := FALSE;
        nGearState := 0;
      ELSE
        nGearState := 30;
      END_IF;
    END_IF;
    IF DustAxis_GearOut.Error THEN
      DustAxis_GearOut.Execute := FALSE;
      g_bDAxisGearInError := TRUE;
      bGearCheck := FALSE;
      nGearState := 0;
    END_IF;
  30:
    DustAxis_Stop.Execute := TRUE;
    IF DustAxis_Stop.Done THEN
      DustAxis_Stop.Execute := FALSE;
      nGearState := 0;
    END_IF;
    IF DustAxis_Stop.Commandaborted OR DustAxis_Stop.Error THEN
      DustAxis_Stop.Execute := FALSE;
      nGearState := 0;
    END_IF;
    bGearCheck := FALSE;
  40:
    IF D_Axis.NCTOPLC.AxisState = 8 THEN
      IF ABS(ABS(g_fCurrentCoordYBuffer-dCoordY)-ABS(D_Axis.NCTOPLC.ACTPOS-dCoordD))> dCoordMaxDiff THEN
          g_bDAxisGearError := TRUE;
      END_IF;
    ELSE
      bGearCheck := FALSE;
      nGearState := 0;
    END_IF;
END_CASE;
